from pathlib import Path

import mlflow
from mlflow import MlflowClient

PROJECT_ROOT = Path(__file__).resolve().parents[2]
DB_PATH = PROJECT_ROOT / "lesson13" / "mlops" / "mlflow.db"

mlflow.set_tracking_uri(f"sqlite:///{DB_PATH.as_posix()}")

client = MlflowClient()

MODEL_NAME = "customer-churn-classifier"
RUN_ID = "bc13d1a6fe6445a384dc0ba63b2328b2"

# MLflow 3 records logged models separately from runs.
# Retrieve the model generated by our selected experiment.
experiment = client.get_experiment_by_name(
    "customer-churn-model-comparison"
)

if experiment is None:
    raise RuntimeError("Experiment not found")

logged_models = client.search_logged_models(
    experiment_ids=[experiment.experiment_id],
    filter_string=f"source_run_id = '{RUN_ID}'",
)

if not logged_models:
    raise RuntimeError(
        f"No logged model found for run {RUN_ID}"
    )

if len(logged_models) != 1:
    raise RuntimeError(
        f"Expected one logged model, found {len(logged_models)}"
    )

model = logged_models[0]

print("Selected logged model:", model.model_id)

# Register the exact logged model.
registered = mlflow.register_model(
    model_uri=f"models:/{model.model_id}",
    name=MODEL_NAME,
)

print("Registered model:", registered.name)
print("Version:", registered.version)

# Tag the version with its evaluation results.
client.set_model_version_tag(
    name=MODEL_NAME,
    version=registered.version,
    key="validation_auc",
    value="0.9593183412290704",
)

client.set_model_version_tag(
    name=MODEL_NAME,
    version=registered.version,
    key="approval_status",
    value="lab_approved",
)

# Promote the version through an alias.
client.set_registered_model_alias(
    name=MODEL_NAME,
    alias="champion",
    version=registered.version,
)

print("\nChampion alias assigned.")
print(f"Model URI: models:/{MODEL_NAME}@champion")
